package com.wipro.hibernate;import java.math.BigDecimal;public class Flower{private String flowerId,flowerName,color;private BigDecimal price;public Flower(){}public String getFlowerId(){return flowerId;}public void setFlowerId(String v){flowerId=v;}public String getFlowerName(){return flowerName;}public void setFlowerName(String v){flowerName=v;}public String getColor(){return color;}public void setColor(String v){color=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}}